<?php require_once 'layout.php'; require_auth(); if(is_admin()) redirect(BASE_URL.'/admin.php');
$uid=$_SESSION['user_id'];$itemsStmt=db()->prepare('SELECT c.quantity,p.* FROM cart c JOIN products p ON p.id=c.product_id WHERE c.user_id=?');$itemsStmt->execute([$uid]);$items=$itemsStmt->fetchAll(); if(!$items) redirect(BASE_URL.'/cart.php');
if($_SERVER['REQUEST_METHOD']==='POST'){
 $fullname=trim($_POST['fullname']??'');$phone=preg_replace('/\D/','',$_POST['phone']??'');$province=$_POST['province']??'';$district=$_POST['district']??'';$neighborhood=$_POST['neighborhood']??'';$address=trim($_POST['address']??'');$card=preg_replace('/\D/','',$_POST['card_number']??'');$cvv=preg_replace('/\D/','',$_POST['cvv']??'');$expiry=trim($_POST['expiry']??'');$cardName=trim($_POST['card_name']??'');$currency=in_array($_POST['currency']??'TRY',['TRY','USD','EUR'])?$_POST['currency']:'TRY';
 if(!$fullname||strlen($phone)!==10||!$province||!$district||!$neighborhood||!$address||strlen($card)!==16||strlen($cvv)!==3||!preg_match('/^(0[1-9]|1[0-2])\/\d{2}$/',$expiry)||!$cardName){flash('Lütfen telefon 10 hane, kart 16 hane, CVV 3 hane olacak şekilde tüm alanları doldur.');}
 else{
  $total=0; foreach($items as $it){ if($it['quantity']>$it['stock']){flash('Sepette stoktan fazla ürün var.'); redirect(BASE_URL.'/cart.php');} $total+=$it['quantity']*$it['price']; }
  $rates=fx_rates(); $converted=convert_amount($total,$currency);
  $pdo=db();$pdo->beginTransaction();
  $pdo->prepare('INSERT INTO orders(user_id,total,fullname,phone,province,district,neighborhood,address,card_last4,currency,converted_total,rate_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$uid,$total,$fullname,$phone,$province,$district,$neighborhood,$address,substr($card,-4),$currency,$converted,$rates['date']]);$oid=$pdo->lastInsertId();
  foreach($items as $it){$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)')->execute([$oid,$it['id'],$it['name'],$it['price'],$it['quantity']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$it['quantity'],$it['id']]);}
  if(isset($_POST['save_address']))$pdo->prepare('INSERT INTO addresses(user_id,title,fullname,phone,province,district,neighborhood,address) VALUES(?,?,?,?,?,?,?,?)')->execute([$uid,'Teslimat Adresim',$fullname,$phone,$province,$district,$neighborhood,$address]);
  if(isset($_POST['save_card']))$pdo->prepare('INSERT INTO cards(user_id,card_name,card_last4,expiry) VALUES(?,?,?,?)')->execute([$uid,$cardName,substr($card,-4),$expiry]);
  $pdo->prepare('DELETE FROM cart WHERE user_id=?')->execute([$uid]);$pdo->commit(); flash('Siparişin alındı. Admin panelindeki siparişlere düştü.'); redirect(BASE_URL.'/profile.php#orders');
 }}
$total=0; foreach($items as $it){$total+=$it['quantity']*$it['price'];} $rates=fx_rates(); $cur=get_currency(); $shownTotal=convert_amount($total,$cur); page_header('Satın Al'); ?>
<h1 class="page-title">Satın Alma</h1><form method="post" class="card form nice-form" onsubmit="return confirmCheckoutCurrency()"><h2>🚚 Teslimat Bilgileri</h2><input name="fullname" placeholder="Ad Soyad" required><input name="phone" placeholder="Telefon: 5xxxxxxxxx" oninput="onlyDigits(this,10)" maxlength="10" minlength="10" inputmode="numeric" required><div class="row"><select class="province" data-district="#district" data-neighborhood="#neighborhood" name="province" onchange="updateDistrict(this)" required></select><select id="district" name="district" onchange="updateNeighborhood(this)" required></select></div><select id="neighborhood" name="neighborhood" required></select><textarea name="address" placeholder="Açık adres" required></textarea><label class="check"><input type="checkbox" name="save_address" checked> Adresi Profilim'e kaydet</label><h2>💱 Para Birimi</h2><div class="currency-confirm"><p><b>Sepette seçili para birimi:</b> <span id="selectedCurrencyLabel"><?=h($cur)?></span></p><p class="muted">Bu para birimiyle devam edebilirsin veya aşağıdan değiştirebilirsin.</p></div><select name="currency" id="checkoutCurrency" onchange="updateCheckoutTotal(<?=$total?>); syncCurrencyLabel();"><option value="TRY" <?=$cur==='TRY'?'selected':''?>>TL</option><option value="USD" <?=$cur==='USD'?'selected':''?>>Dolar / USD</option><option value="EUR" <?=$cur==='EUR'?'selected':''?>>Euro / EUR</option></select><p class="total-box" data-total-try="<?=$total?>">Tahmini çekilecek tutar: <b id="checkoutTotal"><?=money($total,$cur)?></b></p><p class="muted small">Kur Frankfurter üzerinden günlük alınır; internet yoksa yedek kurla hesaplanır. Kur tarihi: <?=h($rates['date'])?></p><h2>💳 Kart Bilgileri</h2><input name="card_name" placeholder="Kart Üzerindeki İsim" required><input name="card_number" placeholder="Kart Numarası - 16 hane" oninput="onlyDigits(this,16)" maxlength="16" minlength="16" inputmode="numeric" required><div class="row"><input name="expiry" placeholder="AA/YY" maxlength="5" pattern="(0[1-9]|1[0-2])/\d{2}" required><input name="cvv" placeholder="CVV - 3 hane" oninput="onlyDigits(this,3)" maxlength="3" minlength="3" inputmode="numeric" required></div><label class="check"><input type="checkbox" name="save_card" checked> Kartın son 4 hanesini Profilim'e kaydet</label><button class="btn primary big" style="width:100%">Siparişi Tamamla</button></form><script>window.fxRates={TRY:1,USD:<?=$rates['USD']?>,EUR:<?=$rates['EUR']?>};window.checkoutInitialCurrency='<?=h($cur)?>';</script>
<?php page_footer(); ?>
